    f1it: [{ k: 'bank', f0: 0.64, f1: 0.8, side: 'in', o0: 14, o1: 56 }, { k: 'stand', f0: 0.94, f1: 0.02, side: 'out', len: 110 }, { k: 'bill', f: 0.98, side: 'in', off: 4, w: 28, h: 6, text: 'MONZA', bg: '#b3121f', fg: '#ffffff' }],
    f1jp: [{ k: 'wheel', f: 0.12, side: 'out', off: 80 }, { k: 'stand', f0: 0.96, f1: 0.03, side: 'out', len: 100 }],
    f1us: [{ k: 'tower', f: 0.035, side: 'in', off: 80, w: 14, h: 80, needle: 1 }, { k: 'stand', f0: 0.96, f1: 0.03, side: 'out', len: 100 }],
