  /// A circuit's distant skyline, painted once on a strip that wraps right round the horizon (see makeSkyline).
  const F1_SKY = { f1sg: 'bay', f1lv: 'strip', f1ae: 'yas', f1mc: 'monaco', f1mi: 'miami', f1jp: 'hills', f1be: 'ardennes', f1us: 'austin' };
