    let seed = 11 + kind.length * 977; const rnd = () => { seed = (Math.imul(seed, 1103515245) + 12345) >>> 0; return seed / 4294967296; };
    const pal = { bay: ['#2b3547', '#34405a', '#222b3b', '#3d4a66'], strip: ['#3a2a4a', '#2a3a55', '#4a2f3a', '#243046'], yas: ['#5b4a52', '#6a5a60', '#4a4048'], monaco: ['#d9b99a', '#e3cba6', '#c9a98a', '#e8d5b7', '#cfae8c'], miami: ['#8aa4b8', '#9bb3c4', '#7a93a8', '#b3c5d2'], austin: ['#7d8a96', '#6f7c88'] }[kind] || ['#5a6670'];
