      for (let L = 0; L < 3; L++) { c.fillStyle = dim(['#2d4a33', '#26402b', '#1f3624'][L]); c.beginPath(); c.moveTo(0, h); for (let x = 0; x <= w; x += 6) c.lineTo(x, h * (0.7 - L * 0.12) - Math.sin(x / w * Math.PI * 2 * (3 + L)) * h * 0.1 - Math.sin(x / 31 + L) * 3); c.lineTo(w, h); c.fill(); }
      if (kind === 'hills') { const x = w * 0.62, r = h * 0.55, y = h - r - 8; c.strokeStyle = dim('#c9ced6'); c.lineWidth = 2; c.beginPath(); c.arc(x, y, r, 0, 7); c.stroke(); for (let s = 0; s < 8; s++) { const a = s * Math.PI / 4; c.beginPath(); c.moveTo(x, y); c.lineTo(x + Math.cos(a) * r, y + Math.sin(a) * r); c.stroke(); } c.beginPath(); c.moveTo(x - r * 0.5, h); c.lineTo(x, y); c.lineTo(x + r * 0.5, h); c.stroke(); }
