    if (kind === 'bay') special(w * 0.18, (x) => { for (let t = 0; t < 3; t++) bld(x + t * 34, 22, h * 0.92, '#4a5a78'); c.fillStyle = dim('#cfd6e2'); c.fillRect(x - 10, h * 0.1, 3 * 34 + 20, 6); });
    if (kind === 'bay') special(w * 0.65, (x) => { c.strokeStyle = dim('#aeb6c4'); c.lineWidth = 2; c.beginPath(); c.arc(x, h * 0.5, h * 0.42, 0, 7); c.stroke(); });
    if (kind === 'strip') { special(w * 0.3, (x) => { c.fillStyle = dim('#8a8f98'); c.fillRect(x, h * 0.1, 4, h * 0.9); c.fillRect(x - 8, h * 0.4, 20, 6); }); special(w * 0.7, (x) => { c.fillStyle = dim('#9a8f86'); c.beginPath(); c.moveTo(x, h * 0.2); c.lineTo(x - 14, h); c.lineTo(x + 14, h); c.fill(); }); }
