    const q = ahead(look), off = inPit ? P.side * (rel < P.a + 40 || rel > P.b - 40 ? (T.width / 2 + P.lane) / 2 + 2 : P.lane + (st.pitOff || 0)) : clamp(own * (1 - lineW) + line * lineW, -half, half);
