      for (const r of racers) { const x = Math.random(); r.car.tyre = r === me ? myTyre : x < 0.35 ? 'S' : x < 0.75 ? 'M' : 'H'; r.tyreLap = 0; r.pits = 0; r.code = String(r.name || '').replace(/[^A-Za-z]/g, '').slice(0, 3).toUpperCase() || 'CAR'; }
